#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include <iostream>
#include <set>
#include <queue>
static void dump(const Graph&g,uint32_t id){const auto&e=g.elements.at(id);std::cout<<"element="<<id<<" type="<<g.strings[e.type]<<" name="<<g.strings[e.name]<<"\n";for(const auto&a:e.attributes){std::cout<<" attribute="<<g.strings[a.name]<<" type="<<unsigned(a.type)<<" count="<<a.values.size();for(const auto&v:a.values){unsigned scalar=a.type>=15?a.type-14:a.type;if(scalar==1)std::cout<<" ref="<<v.reference;else if(scalar==5)std::cout<<" text="<<v.text;}std::cout<<"\n";}}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto g=loadGraph(argv[1]);for(uint32_t root:{32170u,33602u}){std::set<uint32_t>seen;std::queue<uint32_t>pending;pending.push(root);size_t materials=0,parameters=0;while(!pending.empty()){auto id=pending.front();pending.pop();if(id>=g.elements.size()||!seen.insert(id).second)continue;const auto&e=g.elements[id];bool interesting=id==root;auto type=g.strings[e.type];if(type.find("Material")!=std::string::npos){interesting=true;++materials;}for(const auto&a:e.attributes){auto name=g.strings[a.name];if(!name.empty()&&name[0]=='$'){interesting=true;++parameters;}unsigned scalar=a.type>=15?a.type-14:a.type;if(scalar==1)for(const auto&v:a.values)if(v.reference<g.elements.size())pending.push(v.reference);}if(interesting)dump(g,id);}std::cout<<"model="<<root<<" reachable_elements="<<seen.size()<<" material_elements="<<materials<<" dollar_parameters="<<parameters<<"\n";}size_t global=0;for(uint32_t id=0;id<g.elements.size();++id){bool match=false;for(const auto&a:g.elements[id].attributes)if(g.strings[a.name]=="$basetexture")match=true;if(match){dump(g,id);++global;}}std::cout<<"global_basetexture_override_elements="<<global<<" dynamic_runtime_overrides=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
